// Solved: the Think and Reflect questions, Exercise Sets 12.1, 12.2, 12.3 and 12.4, and the end-of-chapter exercises.
// Not solved, because the question is a picture that cannot be read from the text: end-of-chapter question 2 (the lines drawn on paper)
// and question 24 (the shaded part of the square).
// NOTE: a slash inside text is shown as a stacked fraction on screen, so ÷ is used for division.

let n = 0;
const Q = (
  questionNumber: string, question: string, given: Record<string, string>, formulaUsed: string,
  derivationSteps: string[], finalAnswer: string, conceptualTip?: string, figure?: GeoSpec,
): NCERTSolvedQuestion => ({ id: ++n, questionNumber, question, given, formulaUsed, derivationSteps, finalAnswer, conceptualTip, figure });

